import * as searchService from "@/server/services/search-service";
import { rateLimitState } from "../server/_support/doubles/misc";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
let tenant: Tenant;
let detach: Unsubscribe;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detach = searchService.registerSearchListeners();
  tenant = await createTenant("searchsvc", "growth");
});

afterAll(() => {
  detach();
  cleanup();
});

afterEach(() => {
  rateLimitState.allowed = true;
  rateLimitState.remaining = 100;
});

describe("services/search-service", () => {
  it("indexes an issue and a comment on creation", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Zulu index target" }),
    );
    const comment = await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "Yankee index target",
      parentId: null,
      mentionedUserIds: [],
    });

    const issueHits = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "Zulu",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });
    expect(issueHits.total).toBe(1);
    expect(issueHits.items[0]).toMatchObject({ kind: "issue", id: issue.id });

    const commentHits = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "Yankee",
      kinds: ["comment"],
      limit: 25,
      cursor: null,
    });
    expect(commentHits.total).toBe(1);
    expect(commentHits.items[0]).toMatchObject({ kind: "comment", id: comment.id });
  });

  it("re-indexes an updated issue in place", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Original Title Marker" }),
    );

    await issueService.updateIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      title: "Updated Title Marker",
    });

    const stale = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "Original Title Marker",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });
    expect(stale.total).toBe(0);

    const fresh = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "Updated Title Marker",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });
    expect(fresh.total).toBe(1);
    expect(fresh.items[0]).toMatchObject({ id: issue.id });
  });

  it("drops an archived issue from the index", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "ArchiveIndexMarker" }),
    );

    const before = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "ArchiveIndexMarker",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });
    expect(before.total).toBe(1);

    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);

    const after = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "ArchiveIndexMarker",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });
    expect(after.total).toBe(0);
  });

  it("never returns another tenant's rows", async () => {
    const other = await createTenant("searchsvcother", "growth");
    await issueService.createIssue(
      other.actors.member,
      issueInput(other.org.id, other.project.id, { title: "CrossTenantMarker" }),
    );

    const hits = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "CrossTenantMarker",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });

    expect(hits.total).toBe(0);
    expect(hits.items).toHaveLength(0);
  });

  it("falls back to plain matching when advanced_search is off", async () => {
    // The tenant is on "growth", which does not include advanced_search.
    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "PlainMatchWorks" }),
    );

    await expect(
      searchService.search(tenant.actors.member, {
        orgId: tenant.org.id,
        q: "PlainMatchWorks",
        kinds: ["issue"],
        limit: 25,
        cursor: null,
      }),
    ).resolves.toMatchObject({ total: 1 });

    await expect(
      searchService.search(tenant.actors.member, {
        orgId: tenant.org.id,
        q: "status:PlainMatchWorks",
        kinds: ["issue"],
        limit: 25,
        cursor: null,
      }),
    ).rejects.toThrow(/not included in this plan/);
  });

  it("rate-limits search queries per organization", async () => {
    rateLimitState.allowed = false;

    await expect(
      searchService.search(tenant.actors.member, {
        orgId: tenant.org.id,
        q: "anything",
        kinds: ["issue"],
        limit: 25,
        cursor: null,
      }),
    ).rejects.toThrow(/rate limit/i);
  });
});
/**
 * Private paging helpers shared by the repositories in this directory.
 *
 * Not part of the public data-access surface — repositories re-export nothing
 * from here. Keyset (cursor) pagination is expressed as a row-value comparison
 * so a page boundary is stable even when two rows share a `created_at`.
 */
import { sql } from "drizzle-orm";
import { decodeCursor, encodeCursor } from "./base-repository";
import { makePage } from "@/types/common";
import type { Page } from "@/types/common";
import type { SQL } from "drizzle-orm";
import type { SQLiteColumn } from "drizzle-orm/sqlite-core";

export interface KeysetSort {
  readonly sortColumn: SQLiteColumn;
  readonly idColumn: SQLiteColumn;
}

/**
 * Predicate that resumes a descending listing after `cursor`. Returns
 * `undefined` for a first page or an unparseable cursor — a bad cursor
 * degrades to "start from the top", never to an error page.
 */
export function keysetPredicate(
  sort: KeysetSort,
  cursor: string | null | undefined,
): SQL | undefined {
  if (!cursor) return undefined;
  const decoded = decodeCursor(cursor);
  if (!decoded) return undefined;

  return sql`(${sort.sortColumn}, ${sort.idColumn}) < (${decoded.sortValue}, ${decoded.id})`;
}

/** SQLite tolerates a `LIMIT` of `n + 1`; that extra row is the has-more probe. */
export function probeLimit(limit: number): number {
  return Math.max(1, Math.min(limit, 100)) + 1;
}

/**
 * Turns an over-fetched row array into a `Page`, dropping the probe row and
 * deriving the next cursor from the last row that survived.
 */
export function toPage<TRow, TOut>(
  rows: readonly TRow[],
  limit: number,
  total: number,
  map: (row: TRow) => TOut,
  cursorOf: (row: TRow) => { id: string; sortValue: string },
): Page<TOut> {
  const capped = Math.max(1, Math.min(limit, 100));
  const hasMore = rows.length > capped;
  const visible = hasMore ? rows.slice(0, capped) : rows;
  const last = visible.at(-1);

  const nextCursor =
    hasMore && last
      ? encodeCursor(cursorOf(last).id, cursorOf(last).sortValue)
      : null;

  return makePage(visible.map(map), nextCursor, total);
}

/** Drops the `undefined` slots so `and(...)` never sees a hole. */
export function compact(
  ...predicates: readonly (SQL | undefined)[]
): readonly SQL[] {
  return predicates.filter((value): value is SQL => value !== undefined);
}

/**
 * Wrapper shared by every Server Action: parses with a Zod schema, resolves the
 * `Actor`, maps thrown domain errors to an `AppErrorShape` and revalidates the
 * affected tags.
 *
 * Owner D. Every mutation in `src/actions/**` funnels through here so the four
 * things each one must do — validate, authenticate, translate errors,
 * revalidate — happen in exactly one place.
 *
 * Must call (do not reimplement): getActor, toActionResult, revalidateTagged
 */

import { getActor, requireActorFor } from "@/lib/actor";
import { CACHE_PROFILES, revalidateTagged } from "@/lib/cache";
import { toActionResult } from "@/lib/errors";
import { getSessionPrincipal } from "@/lib/session";
import type { ActionResult } from "@/types/api";
import type { OrgId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { ZodType } from "zod";
import { UnauthorizedActionError } from "./action-errors";

/** The body of an action: already-validated input plus the resolved principal. */
export type ActionHandler = (input: unknown, actor: Actor) => Promise<unknown>;

export type ActionOptions = {
  /**
   * When `true` (the default) the organization is taken from the parsed input —
   * either an `orgSlug` or an `orgId` field. When `false` the action does not
   * name an organization and the session's active org is used instead.
   */
  requireOrg?: boolean;
  /** Static cache tags invalidated once the handler resolves. */
  revalidate?: readonly string[];
  /** cacheLife profile handed to `revalidateTag` — required in Next 16. */
  cacheProfile?: string;
};

type OrgBearingInput = { orgSlug?: unknown; orgId?: unknown };

/**
 * Resolves the actor for one action call.
 *
 * `getActor(orgSlug)` is the primary path because most mutations are dispatched
 * from a `[orgSlug]` route; actions whose payload carries the branded `orgId`
 * instead resolve through `requireActorFor()`.
 */
async function resolveActorFor(input: unknown, fromInput: boolean): Promise<Actor> {
  if (fromInput && typeof input === "object" && input !== null) {
    const record = input as OrgBearingInput;
    if (typeof record.orgSlug === "string" && record.orgSlug.length > 0) {
      return getActor(record.orgSlug);
    }
    if (typeof record.orgId === "string" && record.orgId.length > 0) {
      return requireActorFor(record.orgId as OrgId);
    }
  }

  const principal = await getSessionPrincipal();
  if (principal === null || principal.activeOrgId === null) {
    throw new UnauthorizedActionError();
  }
  return requireActorFor(principal.activeOrgId);
}

/** Adds the monotonic token `useActionState` uses to tell two results apart. */
function stamp<T>(result: ActionResult<T>): ActionResult<T> {
  const submittedAt = new Date().toISOString();
  return result.ok
    ? { ok: true, data: result.data, submittedAt }
    : { ok: false, error: result.error, submittedAt };
}

export function withAction<TSchema extends ZodType, TData>(
  schema: TSchema,
  handler: ActionHandler,
  options: ActionOptions = {},
): (raw: unknown) => Promise<ActionResult<TData>> {
  return async function runAction(raw: unknown): Promise<ActionResult<TData>> {
    const parsed = schema.safeParse(raw);
    if (!parsed.success) {
      return stamp(toActionResult(parsed.error));
    }

    try {
      const actor = await resolveActorFor(parsed.data, options.requireOrg !== false);
      const data = (await handler(parsed.data, actor)) as TData;

      const tags = options.revalidate ?? [];
      if (tags.length > 0) {
        revalidateTagged(tags, options.cacheProfile ?? CACHE_PROFILES.minutes);
      }

      return stamp({ ok: true, data });
    } catch (error) {
      return stamp(toActionResult(error));
    }
  };
}
/**
 * Error types raised by Server Actions that are *expected* failures rather
 * than bugs. Each one carries the `ErrorCode` that `toAppError()` maps into
 * the `AppErrorShape` the client form layer renders, mirroring the convention
 * already used by `PermissionDeniedError` and `TenantScopeError`.
 *
 * These live in `src/actions/_lib` because only the action layer produces
 * them — services throw their own domain errors, and repositories throw none.
 */

import type { LimitedResource } from "@/types/billing";
import type { IsoTimestamp } from "@/types/common";
import type { PermissionAction } from "@/types/permission";

/** No session at all, or a session whose active organization is gone. */
export class UnauthorizedActionError extends Error {
  readonly code = "unauthorized" as const;

  constructor(message = "Sign in to continue.") {
    super(message);
    this.name = "UnauthorizedActionError";
  }
}

/**
 * `can()` returned false. Distinct from `PermissionDeniedError` (thrown by
 * `assertCan()` inside services) only in that the action layer already knows
 * the action name and does not need the full `PermissionDecision`.
 */
export class ForbiddenActionError extends Error {
  readonly code = "forbidden" as const;

  constructor(readonly action: PermissionAction) {
    super(`Permission denied: ${action}`);
    this.name = "ForbiddenActionError";
  }
}

/** A plan quota from `@/config/plan-limits` would be breached. */
export class PlanLimitError extends Error {
  readonly code = "plan_limit_exceeded" as const;

  constructor(
    readonly resource: LimitedResource,
    readonly limit: number,
    readonly used: number,
  ) {
    super(`Plan limit reached for ${resource}: ${used}/${limit}`);
    this.name = "PlanLimitError";
  }
}

/** The token bucket in `@/lib/rate-limit` refused the request. */
export class RateLimitedError extends Error {
  readonly code = "rate_limited" as const;

  constructor(
    readonly bucketKey: string,
    readonly resetAt: IsoTimestamp,
  ) {
    super(`Rate limit exceeded for ${bucketKey}; retry after ${resetAt}`);
    this.name = "RateLimitedError";
  }
}

/** A feature flag that gates the whole action is off for this organization. */
export class FeatureUnavailableError extends Error {
  readonly code = "forbidden" as const;

  constructor(readonly flag: string) {
    super(`Feature not available: ${flag}`);
    this.name = "FeatureUnavailableError";
  }
}

/** The row the action addresses does not exist inside the actor's tenant. */
export class ActionNotFoundError extends Error {
  readonly code = "not_found" as const;

  constructor(readonly what: string) {
    super(`Not found: ${what}`);
    this.name = "ActionNotFoundError";
  }
}
/**
 * Token-bucket limiter applied to invites, comments, search and password
 * resets.
 *
 * Buckets are keyed by `(orgId, bucketKey)` and held in process — Taskflow
 * runs single-writer, and the corpus has no external cache. Capacity scales
 * with the org's plan through `getPlanLimits()`, so a growth org is not held
 * to a free org's ceiling; the per-bucket shape below is the base rate.
 */
import { getPlanLimits } from "@/config/plan-limits";
import type { PlanId } from "@/types/billing";
import type { IsoTimestamp, OrgId } from "@/types/common";
import { toIsoTimestamp } from "@/types/common";

export type RateLimitVerdict = {
  allowed: boolean;
  remaining: number;
  resetAt: IsoTimestamp;
};

export type RateLimitConfig = { capacity: number; refillPerMinute: number };

export const RATE_LIMIT_BUCKETS: Readonly<Record<string, RateLimitConfig>> = {
  "member:invite": { capacity: 20, refillPerMinute: 2 },
  "comment:create": { capacity: 60, refillPerMinute: 20 },
  "issue:create": { capacity: 60, refillPerMinute: 20 },
  "search:query": { capacity: 120, refillPerMinute: 60 },
  "auth:password-reset": { capacity: 5, refillPerMinute: 1 },
  "webhook:deliver": { capacity: 100, refillPerMinute: 50 },
};

/** Applied to any key not in the table above. */
const DEFAULT_BUCKET: RateLimitConfig = { capacity: 30, refillPerMinute: 10 };

type BucketState = { tokens: number; updatedAt: number };

const buckets = new Map<string, BucketState>();

/** Plan-aware org context; services set this when they know the org's plan. */
const planByOrg = new Map<OrgId, PlanId>();

/** Records an org's plan so subsequent bucket sizes scale with its quota. */
export function setOrgPlan(orgId: OrgId, plan: PlanId): void {
  planByOrg.set(orgId, plan);
}

export function getBucketConfig(bucketKey: string): RateLimitConfig {
  return RATE_LIMIT_BUCKETS[bucketKey] ?? DEFAULT_BUCKET;
}

/**
 * Scales the base bucket by the org's hourly API allowance, so the limiter
 * and the plan catalogue can never drift apart: the plan is the source of
 * the ceiling, this table only sets the relative shape.
 */
function configFor(orgId: OrgId, bucketKey: string): RateLimitConfig {
  const base = getBucketConfig(bucketKey);
  const plan = planByOrg.get(orgId) ?? "free";
  const hourly = getPlanLimits(plan).apiRequestsPerHour;
  const factor = Number.isFinite(hourly) ? Math.max(1, hourly / 100) : 100;

  return {
    capacity: Math.min(base.capacity * factor, base.capacity * 100),
    refillPerMinute: Math.min(
      base.refillPerMinute * factor,
      base.refillPerMinute * 100,
    ),
  };
}

/**
 * Spends `cost` tokens from the bucket, refilling first for the elapsed time.
 * Async because the production limiter is expected to move behind a store —
 * every call site already awaits it.
 */
export async function consumeRateLimit(
  orgId: OrgId,
  bucketKey: string,
  cost = 1,
): Promise<RateLimitVerdict> {
  const config = configFor(orgId, bucketKey);
  const key = `${orgId}:${bucketKey}`;
  const nowMs = Date.now();

  const state = buckets.get(key) ?? { tokens: config.capacity, updatedAt: nowMs };
  const elapsedMinutes = (nowMs - state.updatedAt) / 60_000;
  const tokens = Math.min(
    config.capacity,
    state.tokens + elapsedMinutes * config.refillPerMinute,
  );

  const allowed = tokens >= cost;
  const remaining = allowed ? tokens - cost : tokens;
  buckets.set(key, { tokens: remaining, updatedAt: nowMs });

  const deficit = allowed ? config.capacity - remaining : cost - remaining;
  const minutesToReset =
    config.refillPerMinute > 0 ? Math.max(0, deficit) / config.refillPerMinute : 0;

  return {
    allowed,
    remaining: Math.floor(remaining),
    resetAt: toIsoTimestamp(new Date(nowMs + minutesToReset * 60_000)),
  };
}

/** Test-only: drops every bucket and org plan association. */
export function resetRateLimits(): void {
  buckets.clear();
  planByOrg.clear();
}
import {
  FEATURE_FLAG_DEFINITIONS,
  FEATURE_FLAG_KEYS,
} from "@/config/feature-flags";
import { planAtLeast } from "@/config/plan-limits";
import { ROLE_RANK } from "@/types/member";
import type {
  FeatureFlagKey,
  FeatureFlagSnapshot,
  FlagContext,
} from "@/types/feature-flag";

/**
 * Feature-flag evaluation, shared verbatim by server and client.
 *
 * Server code builds a `FlagContext` from the session and calls `isEnabled()`
 * directly; the dashboard layout serialises `snapshotFlags()` into the client
 * provider so `useFeatureFlag()` answers the same way without a round trip.
 * Both sides must agree — never re-implement a strategy at a call site.
 */
export function isEnabled(flag: FeatureFlagKey, ctx: FlagContext): boolean {
  const definition = FEATURE_FLAG_DEFINITIONS[flag];
  if (!definition) return false;

  if (definition.overridable && ctx.overrides?.includes(flag)) {
    return true;
  }

  const strategy = definition.strategy;
  switch (strategy.kind) {
    case "off":
      return false;
    case "on":
      return true;
    case "plan":
      return planAtLeast(ctx.plan, strategy.minPlan);
    case "role":
      return ctx.role !== null && ROLE_RANK[ctx.role] >= ROLE_RANK[strategy.minRole];
    case "percentage":
      return bucketOf(flag, ctx) < strategy.percent;
    default:
      return false;
  }
}

/** Evaluates every flag at once, for handoff to the client provider. */
export function snapshotFlags(ctx: FlagContext): FeatureFlagSnapshot {
  const snapshot = {} as Record<FeatureFlagKey, boolean>;
  for (const key of FEATURE_FLAG_KEYS) {
    snapshot[key] = isEnabled(key, ctx);
  }
  return snapshot;
}

/** Throwing guard for server actions gated behind a flag. */
export class FeatureDisabledError extends Error {
  readonly code = "forbidden" as const;

  constructor(readonly flag: FeatureFlagKey) {
    super(`Feature "${flag}" is not enabled for this organization.`);
    this.name = "FeatureDisabledError";
  }
}

export function assertEnabled(flag: FeatureFlagKey, ctx: FlagContext): void {
  if (!isEnabled(flag, ctx)) {
    throw new FeatureDisabledError(flag);
  }
}

/**
 * Deterministic 0–99 bucket for percentage rollouts. Stable per
 * (flag, org, user) so a viewer never sees the feature flicker.
 */
function bucketOf(flag: FeatureFlagKey, ctx: FlagContext): number {
  const seed = `${flag}:${ctx.orgId ?? "-"}:${ctx.userId ?? "-"}`;
  let hash = 2_166_136_261;
  for (let i = 0; i < seed.length; i += 1) {
    hash ^= seed.charCodeAt(i);
    hash = Math.imul(hash, 16_777_619);
  }
  return Math.abs(hash) % 100;
}
/**
 * Server-side flag context construction and the org-level override toggle.
 *
 * Must call (do not reimplement): assertCan, isEnabled, snapshotFlags, emit
 */
import { emit } from "@/lib/event-bus";
import { isEnabled, snapshotFlags } from "@/lib/feature-flags";
import { assertCan } from "@/lib/permissions";
import { getFlagDefinition } from "@/config/feature-flags";
import * as orgRepo from "@/server/repositories/organization-repository";
import { actorEnvelope, orgResource, requireFound } from "./_support";
import type { ToggleFeatureFlagInput } from "@/schemas/feature-flag";
import type { FeatureFlagSnapshot, FlagContext } from "@/types/feature-flag";
import type { Actor } from "@/types/member";
import type { Organization } from "@/types/organization";

/**
 * Builds the evaluation context every `isEnabled()` call needs. Both halves
 * are nullable so marketing pages — no session, no org — can still ask about
 * a flag and get the free-plan answer.
 */
export function buildFlagContext(
  actor: Actor | null,
  org: Organization | null,
): FlagContext {
  return {
    orgId: org?.id ?? actor?.orgId ?? null,
    userId: actor?.userId ?? null,
    plan: org?.plan ?? "free",
    role: actor?.role ?? null,
    overrides: org?.settings.enabledFlagOverrides,
  };
}

/**
 * The serialisable snapshot the dashboard layout hands to the client provider,
 * so `useFeatureFlag()` answers without a round trip and cannot disagree with
 * the server.
 */
export function getSnapshot(
  actor: Actor,
  org: Organization,
): FeatureFlagSnapshot {
  return snapshotFlags(buildFlagContext(actor, org));
}

/**
 * Adds or removes an org-level override. Only flags declared `overridable`
 * accept one — a flag gated purely on plan cannot be switched on by an admin,
 * which is what keeps the plan boundary meaningful.
 */
export async function toggleFlag(
  actor: Actor,
  input: ToggleFeatureFlagInput,
): Promise<Organization> {
  assertCan(actor, "org:manage_flags", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  const definition = getFlagDefinition(input.flag);
  if (!definition.overridable) {
    throw new Error(`Feature "${input.flag}" cannot be overridden per org`);
  }

  const current = new Set(org.settings.enabledFlagOverrides);
  if (input.enabled) {
    current.add(input.flag);
  } else {
    current.delete(input.flag);
  }

  const updated = await orgRepo.updateOrg(input.orgId, {
    orgId: input.orgId,
    settings: { enabledFlagOverrides: [...current] },
  });

  await emit("flag.toggled", {
    ...actorEnvelope(actor),
    flag: input.flag,
    enabled: isEnabled(input.flag, buildFlagContext(actor, updated)),
  });

  return updated;
}

"use server";

/**
 * Updates issue fields.
 *
 * Owner D. Only the fields present in the payload are touched; the service
 * diffs them and emits `issue.updated` with `changedFields` so the activity log
 * can describe the edit without re-reading the row.
 *
 * Must call (do not reimplement): updateIssueSchema, can, getActor,
 * toActionResult
 */

import { ForbiddenActionError } from "@/actions/_lib/action-errors";
import { PENDING_PROJECT_ID } from "@/actions/_lib/permission-resources";
import { withAction } from "@/actions/_lib/with-action";
import { CACHE_PROFILES, issueTag, revalidateTagged } from "@/lib/cache";
import { can } from "@/lib/permissions";
import { updateIssueSchema, type UpdateIssueInput } from "@/schemas/issue";
import { updateIssue } from "@/server/services/issue-service";
import type { ActionResult } from "@/types/api";
import type { Issue } from "@/types/issue";

const run = withAction<typeof updateIssueSchema, Issue>(
  updateIssueSchema,
  async (raw, actor) => {
    const input = raw as UpdateIssueInput;

    const allowed = can(actor, "issue:update", {
      kind: "issue",
      orgId: input.orgId,
      projectId: PENDING_PROJECT_ID,
      issueId: input.issueId,
      authorId: actor.userId,
      assigneeId: actor.userId,
    });
    if (!allowed) {
      throw new ForbiddenActionError("issue:update");
    }

    const issue = await updateIssue(actor, input);
    revalidateTagged([issueTag(issue.id)], CACHE_PROFILES.seconds);
    return issue;
  },
  { revalidate: ["issues"], cacheProfile: "seconds" },
);

export async function updateIssueAction(raw: unknown): Promise<ActionResult<Issue>> {
  return run(raw);
}
/**
